// Generated by `just generate` from `src/plugins/claudetto/slices/decide/domain/text.ts`. Edit the source and run `just generate`.
// The texts that go to Claude: the cause of no Jev answer, the result of the tool, and the prompt of the fallback model.
// Each text follows the strict ASD-STE100 rule, and each sentence gives a reason or a step.

import type { Cause, DecisionRequest } from "../ports.ts";
import {
  CAUSE_FAILED,
  CAUSE_INVALID_KEY,
  CAUSE_MODEL_FAILED,
  CAUSE_NO_BALANCE,
  CAUSE_NO_KEY,
  CAUSE_USAGE,
  FALLBACK_SYSTEM,
  RESULT_FALLBACK,
  RESULT_JEV,
  RESULT_NONE,
} from "../prompts.ts";
import type { Route } from "./route.ts";

/** The sentence that names the cause of no Jev answer. */
export const causeText = (cause: Cause): string => {
  switch (cause) {
    case "no-key":
      return CAUSE_NO_KEY;
    case "invalid-key":
      return CAUSE_INVALID_KEY;
    case "no-balance":
      return CAUSE_NO_BALANCE;
    case "usage":
      return CAUSE_USAGE;
    case "failed":
      return CAUSE_FAILED;
    case "model-failed":
      return CAUSE_MODEL_FAILED;
  }
};

/** The sentence for the cause of a route, with the error text of the failed run when the route has one. */
const whyText = (route: {
  cause: Cause;
  detail?: string | undefined;
}): string =>
  route.detail === undefined
    ? causeText(route.cause)
    : `${causeText(route.cause)} The error was: ${route.detail}`;

/** The result of the tool for a route. Each text names the source of the answer. */
export const resultText = (route: Route): string => {
  switch (route.source) {
    case "jev":
      return RESULT_JEV({ text: route.text });
    case "fallback":
      return RESULT_FALLBACK({ why: whyText(route), text: route.text });
    case "none":
      return RESULT_NONE({ why: whyText(route) });
  }
};

/** The system prompt and the user prompt of the fallback completion. */
export const fallbackPrompt = (
  request: DecisionRequest,
): { system: string; prompt: string } => {
  const system = FALLBACK_SYSTEM;
  const options = (request.options ?? []).map(
    (o) => `- ${o.key}: ${o.description ?? ""}`,
  );
  const parts = [
    `Question: ${request.question}`,
    ...(options.length > 0
      ? ["Options:", ...options]
      : ["Question type: yes or no."]),
    ...(request.state === undefined ? [] : ["State:", request.state]),
  ];
  return { system, prompt: parts.join("\n") };
};
